class Gradebook:
    def __init__(self):
        self.grades = {}
        self.max_points = {}

    def add_student(self, name):
        if name not in self.grades:
            self.grades[name] = {}

    def add_assignment(self, name, max_points, category="default"):
        self.max_points[name] = max_points

    def record(self, student, assignment, points):
        if student not in self.grades:
            self.add_student(student)
        if assignment not in self.grades[student]:
            self.grades[student][assignment] = []
        self.grades[student][assignment].append(points)

    def score(self, student, assignment):
        if student in self.grades and assignment in self.grades[student]:
            return sum(self.grades[student][assignment]) / len(self.grades[student][assignment])
        return 0

    def percent(self, student):
        total_points = 0
        total_max_points = 0
        for assignment in self.grades[student]:
            total_points += self.score(student, assignment)
            total_max_points += self.max_points[assignment]
        return (total_points / total_max_points) * 100 if total_max_points > 0 else 0

    def letter_grade(self, percent):
        if percent >= 90:
            return 'A'
        elif percent >= 80:
            return 'B'
        elif percent >= 70:
            return 'C'
        elif percent >= 60:
            return 'D'
        else:
            return 'F'

    def report(self):
        report = ""
        for student in self.grades:
            report += f"Student: {student}\n"
            for assignment in self.grades[student]:
                report += f"  Assignment: {assignment}, Score: {self.score(student, assignment)}, Max Points: {self.max_points[assignment]}\n"
            report += f"  Percent: {self.percent(student):.2f}%, Letter Grade: {self.letter_grade(self.percent(student))}\n"
        return report

    def set_weight(self, category, weight):
        pass

    def drop_lowest(self, category, n):
        pass

    def set_missing_zero(self, flag):
        pass

    def curve(self, assignment, points):
        if assignment not in self.max_points:
            return 0
        changed_count = 0
        for student in self.grades:
            if assignment in self.grades[student]:
                for i in range(len(self.grades[student][assignment])):
                    new_score = min(self.grades[student][assignment][i] + points, self.max_points[assignment])
                    if new_score != self.grades[student][assignment][i]:
                        self.grades[student][assignment][i] = new_score
                        changed_count += 1
        return changed_count

